#include <stdint.h>
#include "stm32f446xx.h"
#include "stm32f446xx_gpio.h"
#include "led_board.h"
#include "button_board.h"


int main(void)
{
	LED_BOARD_init();
	BUTTON_BOARD_init();
    /* Loop forever */
	while(1){
		if(button_pressed_f){
			LED_BOARD_toggle();
			button_pressed_f = 0;
		}
	};
}
